#!/usr/bin/env perl
# Expands only the macros defined in MACROS.h, leaving everything else untouched.
# usage: expand_macros.pl MACROS.h INPUT.c > OUTPUT.c
# NOTE: Generated by AI
use strict; use warnings;

my ($hdr, $src) = @ARGV;
die "usage: $0 MACROS.h INPUT.c\n" unless defined $src;

my (%obj, %fn);
open my $h, '<', $hdr or die "$hdr: $!";
while (<$h>) {
    if (/^\s*#\s*define\s+(\w+)\(([^)]*)\)\s*(.*?)\s*$/) {
        $fn{$1} = [[map { s/^\s+|\s+$//gr } split /,/, $2], $3];
    } elsif (/^\s*#\s*define\s+(\w+)[ \t]+(\S.*?)\s*$/) {
        $obj{$1} = $2;
    }
}
close $h;

# balanced (...) group
my $P = qr/(?<P>\((?:[^()]++|(?&P))*\))/;

sub split_args {
    my ($s) = @_;
    my @a;
    my $cur = '';
    my $d = 0;
    for my $c (split //, $s) {
        if ($c eq ',' && $d == 0) { push @a, $cur; $cur = ''; next }
        $d++ if $c eq '(';
        $d-- if $c eq ')';
        $cur .= $c;
    }
    push @a, $cur;
    return map { s/^\s+|\s+$//gr } @a;
}

sub expand_fn {
    my ($name, $argstr) = @_;
    my ($params, $body) = @{ $fn{$name} };
    return $body unless @$params;
    my %map;
    @map{@$params} = split_args(substr($argstr, 1, -1));
    my $re = join '|', map quotemeta, @$params;
    # single pass, so substituted args are not rescanned for parameter names
    $body =~ s/\b($re)\b/$map{$1}/g;
    return $body;
}

my $code = do { local $/; open my $s, '<', $src or die "$src: $!"; <$s> };
my $fnre  = join '|', map quotemeta, sort { length $b <=> length $a } keys %fn;
my $objre = join '|', map quotemeta, sort { length $b <=> length $a } keys %obj;

# repeat until nested macro calls are fully expanded
for (1 .. 32) {
    my $prev = $code;
    $code =~ s/\b($fnre)\b\s*($P)/expand_fn($1, $2)/ge if %fn;
    $code =~ s/\b($objre)\b/$obj{$1}/g                 if %obj;
    last if $code eq $prev;
}
print $code;
